def ranger_les_biens(apps, schema_editor):
    """SCI → revenus fonciers ; nom propre avec un lot en LMNP → LMNP, sinon revenus fonciers ; autres sociétés → société ;
    résidence principale → aucune comptabilité."""
    Bien = apps.get_model("patrimoine", "Bien")
    for bien in Bien.objects.select_related("proprietaire"):
        if bien.residence_principale:
            regime = ""
        elif bien.proprietaire.type in ("sci_ir", "sci_is"):
            regime = "foncier"
        elif bien.proprietaire.type == "nom_propre":
            regime = "lmnp" if bien.lots.filter(lmnp=True).exists() else "foncier"
        else:
            regime = "societe"
        Bien.objects.filter(pk=bien.pk).update(comptabilite=regime)


